  --popover: oklch(0.2 0.02 264 / 92%);
  --popover-foreground: oklch(0.96 0.01 264);
  --primary: oklch(0.72 0.11 244);
  --primary-foreground: oklch(0.16 0.02 264);
  --secondary: oklch(1 0 0 / 8%);
  --secondary-foreground: oklch(0.96 0.01 264);
  --muted: oklch(1 0 0 / 6%);
  --muted-foreground: oklch(0.72 0.02 264);
  --accent: oklch(1 0 0 / 8%);
  --accent-foreground: oklch(0.96 0.01 264);
  --destructive: oklch(0.65 0.2 25);
  --warning: oklch(0.8 0.14 79); /* amber — warnings only */
  --warning-foreground: oklch(0.2 0.03 79);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 14%);
  --ring: oklch(0.72 0.11 244 / 60%);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground font-sans;
    min-height: 100dvh;
    background-image:
      radial-gradient(60% 80% at 15% 0%, oklch(0.28 0.06 264 / 55%), transparent 60%),
      radial-gradient(50% 70% at 100% 10%, oklch(0.26 0.07 286 / 45%), transparent 55%),
      linear-gradient(160deg, #0b0e14 0%, #12161f 100%);
    background-attachment: fixed;
  }
  html {
    @apply font-sans;
  }
}

/* Glass surface: apply to cards over the gradient. */
@utility glass {
  background: var(--card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border);
  box-shadow: 0 1px 0 0 oklch(1 0 0 / 6%) inset, 0 8px 30px -12px oklch(0 0 0 / 55%);
  transition: box-shadow 0.3s ease, border-color 0.3s ease, transform 0.3s ease;
}
@utility glass-hover {
  &:hover {
    border-color: oklch(1 0 0 / 18%);
    box-shadow: 0 1px 0 0 oklch(1 0 0 / 10%) inset, 0 10px 40px -10px oklch(0.72 0.11 244 / 35%);
  }
}

